type ParseResult = { ok: true; value: number } | { ok: false; error: string }

function parseNumber(input: string): ParseResult {
    const trimmed = input.trim()
    if (trimmed === "") return { ok: false, error: "bo'sh satr" }
    const value = Number(trimmed)
    if (Number.isNaN(value)) return { ok: false, error: `"${input}" son emas` }
    return { ok: true, value }
}

for (const input of ["42", "  3.14  ", "abc", ""]) {
    const result = parseNumber(input)
    console.log(result.ok ? `✓ ${result.value}` : `✗ ${result.error}`)
}

type Duration = number | { hours?: number; minutes?: number; seconds?: number }

function toSeconds(duration: Duration): number {
    if (typeof duration === "number") return duration
    const { hours = 0, minutes = 0, seconds = 0 } = duration
    return hours * 3600 + minutes * 60 + seconds
}

