type State = "idle" | "running" | "paused" | "stopped"

const transitions: Record<State, State[]> = {
    idle: ["running"],
    running: ["paused", "stopped"],
    paused: ["running", "stopped"],
    stopped: [],
}

function canTransition(from: State, to: State): boolean {
    return transitions[from].includes(to)
}

console.log(canTransition("idle", "running"))
console.log(canTransition("idle", "paused"))
console.log(canTransition("running", "stopped"))
console.log("stopped'dan chiqish yo'q:", transitions.stopped.length === 0)

