type WithUser = { user: { id: number; role: string } }

function withBody<T extends Request>(req: T, body: Record<string, unknown>): T & WithBody {
    return { ...req, body }
}

function withUser<T extends Request>(req: T, user: { id: number; role: string }): T & WithUser {
    return { ...req, user }
}

const base: Request = { url: "/api/posts", method: "POST" }
