class NetworkError extends Error {
    constructor(public statusCode: number) {
        super(`HTTP ${statusCode}`)
    }
}

class ValidationError extends Error {
    constructor(public field: string) {
        super(`${field} noto'g'ri`)
    }
}

function handleError(error: unknown): string {
    if (error instanceof NetworkError) return `Tarmoq xatosi: ${error.statusCode}`
    if (error instanceof ValidationError) return `Validatsiya: ${error.field}`
    if (error instanceof Error) return `Umumiy xato: ${error.message}`
    return "Noma'lum xato"
}

console.log(handleError(new NetworkError(404)))
console.log(handleError(new ValidationError("email")))
