type Expr = { op: "num"; value: number } | { op: "add" | "mul"; left: Expr; right: Expr }
function evaluate(e: Expr): number {
    switch (e.op) {
        case "num": return e.value
        case "add": return evaluate(e.left) + evaluate(e.right)
        case "mul": return evaluate(e.left) * evaluate(e.right)
    }
}
const expr: Expr = { op: "add", left: { op: "num", value: 2 }, right: { op: "mul", left: { op: "num", value: 3 }, right: { op: "num", value: 4 } } }
