type Key = { k: "digit"; d: number } | { k: "op"; op: "+" | "-" } | { k: "eq" } | { k: "clear" }
function press(keys: Key[]): number {
    let acc = 0, cur = 0, op: "+" | "-" = "+"
    const commit = () => { acc = op === "+" ? acc + cur : acc - cur; cur = 0 }
    for (const key of keys) {
        switch (key.k) {
            case "digit": cur = cur * 10 + key.d; break
            case "op": commit(); op = key.op; break
            case "eq": commit(); op = "+"; break
            case "clear": acc = 0; cur = 0; op = "+"; break
        }
    }
    return acc + (op === "+" ? cur : -cur)
}
console.log(press([{ k: "digit", d: 1 }, { k: "digit", d: 2 }, { k: "op", op: "+" }, { k: "digit", d: 8 }, { k: "eq" }]))
console.log(press([{ k: "digit", d: 5 }, { k: "clear" }, { k: "digit", d: 9 }, { k: "op", op: "-" }, { k: "digit", d: 4 }]))

