function partition<T, U extends T>(arr: T[], guard: (x: T) => x is U): [U[], Exclude<T, U>[]] {
    const yes: U[] = [], no: Exclude<T, U>[] = []
    for (const x of arr) guard(x) ? yes.push(x) : no.push(x as Exclude<T, U>)
    return [yes, no]
}
