function invariant(cond: unknown, msg: string): asserts cond {
    if (!cond) throw new Error("Invariant: " + msg)
}
function withdraw(balance: number, amount: number) {
    invariant(amount > 0, "summa musbat bo'lishi kerak")
    invariant(amount <= balance, "mablag' yetarli emas")
    return balance - amount
}
